def longest_up(a):
    if len(a) == 0:
        return 0
    best = cur = 1
    for i in range(1, len(a)):
        if a[i] > a[i - 1]:
            cur += 1
        else:
            cur = 1
        if cur > best:
            best = cur
    return best

def best_row(m):
    best = 0
    best_sum = sum(m[0])
    for r in range(1, len(m)):
        s = 0
        for x in m[r]:
            s += x
        if s > best_sum:
            best_sum = s
            best = r
    return best

print(longest_up([3, 5, 8, 2, 4, 6, 9, 1]), longest_up([]), longest_up([5, 4, 3]))
print(best_row([[1, 2], [9, 0], [4, 4]]))

